self.addEventListener('install',()=>self.skipWaiting());
self.addEventListener('activate',event=>event.waitUntil(self.clients.claim()));
self.addEventListener('fetch',event=>{
 const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==ROOT.origin)return;
 if(IMAGES[decodeURIComponent(url.pathname)]){event.respondWith(fetch(IMAGES[decodeURIComponent(url.pathname)],{mode:'cors',credentials:'omit'}));return;}
 if(!url.pathname.startsWith(ROOT.pathname))return;
 let path=decodeURIComponent(url.pathname.slice(ROOT.pathname.length));if(path.startsWith('_app/')||['asset-worker.js','asset-worker-register.js'].includes(path))return;
 if(IMAGES[path]){event.respondWith(fetch(IMAGES[path],{mode:'cors',credentials:'omit'}));return;}
 if(!path||path.endsWith('/'))path+='index.html';const target=new URL('_app/'+path,ROOT);target.search=url.search;
 event.respondWith(fetch(target,{cache:'no-cache'}).then(response=>{const headers=new Headers(response.headers);headers.delete('content-encoding');headers.delete('content-length');return new Response(response.body,{status:response.status,statusText:response.statusText,headers});}));
});
